"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  Search, Bell, Sun, Moon, LogOut,
} from "lucide-react";

export default function TopNav() {
  const router = useRouter();
  const [theme, setTheme] = useState("dark");
  const [user, setUser] = useState<{ full_name?: string; username?: string; email?: string } | null>(null);

  useEffect(() => {
    // Load theme
    const saved = localStorage.getItem("nexus_theme") || "dark";
    setTheme(saved);
    document.documentElement.setAttribute("data-theme", saved);

    // Load user
    try {
      const u = localStorage.getItem("nexus_user");
      if (u) setUser(JSON.parse(u));
    } catch { /* ignore parse errors */ }
  }, []);

  const toggleTheme = () => {
    const next = theme === "dark" ? "light" : "dark";
    setTheme(next);
    localStorage.setItem("nexus_theme", next);
    document.documentElement.setAttribute("data-theme", next);
  };

  const handleLogout = () => {
    localStorage.removeItem("nexus_token");
    localStorage.removeItem("nexus_user");
    document.cookie = "nexus_token=; path=/; max-age=0; SameSite=Lax";
    router.push("/login");
  };

  const initials = user?.full_name
    ? user.full_name.split(" ").map((n: string) => n[0]).join("").slice(0, 2).toUpperCase()
    : user?.username?.slice(0, 2).toUpperCase() || "NX";

  return (
    <header className="topnav">
      <div className="topnav-search" tabIndex={0} role="button" aria-label="Search (Ctrl+K)">
        <Search size={15} />
        <span>Search commands, data, insights...</span>
        <kbd>⌘K</kbd>
      </div>

      <div className="topnav-actions">
        <button className="topnav-btn" onClick={toggleTheme} aria-label="Toggle theme" title="Toggle theme">
          {theme === "dark" ? <Sun size={18} /> : <Moon size={18} />}
        </button>

        <button className="topnav-btn" aria-label="Notifications" title="Notifications">
          <Bell size={18} />
          <span className="badge" />
        </button>

        <button
          className="topnav-btn"
          onClick={handleLogout}
          aria-label="Log out"
          title="Log out"
          style={{ color: "var(--color-text-muted)" }}
        >
          <LogOut size={18} />
        </button>

        <Link href="/login">
          <div className="topnav-avatar" title={user?.email || "Sign in"}>
            {initials}
          </div>
        </Link>
      </div>
    </header>
  );
}
