"use client";
import {
    BarChart,
    Bar,
    LineChart,
    Line,
    PieChart,
    Pie,
    Cell,
    AreaChart,
    Area,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    ResponsiveContainer,
    Legend,
} from "recharts";
import { useState, useMemo } from "react";

const COLORS = [
    "#facc15", "#38bdf8", "#a78bfa", "#34d399", "#fb923c", "#f472b6",
    "#06b6d4", "#ef4444", "#84cc16", "#e879f9", "#22d3ee", "#fbbf24",
    "#818cf8", "#2dd4bf", "#f97316", "#c084fc",
];

const tooltipStyle = {
    backgroundColor: "rgba(10, 15, 26, 0.95)",
    border: "1px solid rgba(148, 163, 184, 0.15)",
    borderRadius: "10px",
    color: "#f1f5f9",
    fontSize: "12px",
};

type ChartDatum = Record<string, any>;

/* ============================
   BAR CHART
   ============================ */
export function SynBarChart({
    data,
    dataKey,
    nameKey = "name",
    color = "#facc15",
    height = 300,
}: {
    data: ChartDatum[];
    dataKey: string;
    nameKey?: string;
    color?: string;
    height?: number;
}) {
    return (
        <ResponsiveContainer width="100%" height={height}>
            <BarChart data={data} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.04)" />
                <XAxis
                    dataKey={nameKey}
                    tick={{ fill: "#64748b", fontSize: 11 }}
                    axisLine={{ stroke: "rgba(255,255,255,0.08)" }}
                />
                <YAxis tick={{ fill: "#64748b", fontSize: 11 }} axisLine={{ stroke: "rgba(255,255,255,0.08)" }} />
                <Tooltip contentStyle={tooltipStyle} />
                <Bar dataKey={dataKey} fill={color} radius={[4, 4, 0, 0]} />
            </BarChart>
        </ResponsiveContainer>
    );
}

/* ============================
   LINE CHART
   ============================ */
export function SynLineChart({
    data,
    lines,
    xKey = "name",
    height = 300,
}: {
    data: ChartDatum[];
    lines: { key: string; color?: string; name?: string }[];
    xKey?: string;
    height?: number;
}) {
    return (
        <ResponsiveContainer width="100%" height={height}>
            <LineChart data={data} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.04)" />
                <XAxis
                    dataKey={xKey}
                    tick={{ fill: "#64748b", fontSize: 11 }}
                    axisLine={{ stroke: "rgba(255,255,255,0.08)" }}
                />
                <YAxis tick={{ fill: "#64748b", fontSize: 11 }} axisLine={{ stroke: "rgba(255,255,255,0.08)" }} />
                <Tooltip contentStyle={tooltipStyle} />
                <Legend wrapperStyle={{ fontSize: 12, color: "#94a3b8" }} />
                {lines.map((line, i) => (
                    <Line
                        key={line.key}
                        type="monotone"
                        dataKey={line.key}
                        stroke={line.color || COLORS[i % COLORS.length]}
                        strokeWidth={2}
                        dot={{ r: 3, fill: line.color || COLORS[i % COLORS.length] }}
                        name={line.name || line.key}
                    />
                ))}
            </LineChart>
        </ResponsiveContainer>
    );
}

/* ============================
   AREA CHART
   ============================ */
export function SynAreaChart({
    data,
    dataKey,
    xKey = "name",
    color = "#facc15",
    height = 300,
}: {
    data: ChartDatum[];
    dataKey: string;
    xKey?: string;
    color?: string;
    height?: number;
}) {
    return (
        <ResponsiveContainer width="100%" height={height}>
            <AreaChart data={data} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                <defs>
                    <linearGradient id={`grad-${dataKey}`} x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor={color} stopOpacity={0.25} />
                        <stop offset="100%" stopColor={color} stopOpacity={0} />
                    </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.04)" />
                <XAxis dataKey={xKey} tick={{ fill: "#64748b", fontSize: 11 }} axisLine={{ stroke: "rgba(255,255,255,0.08)" }} />
                <YAxis tick={{ fill: "#64748b", fontSize: 11 }} axisLine={{ stroke: "rgba(255,255,255,0.08)" }} />
                <Tooltip contentStyle={tooltipStyle} />
                <Area
                    type="monotone"
                    dataKey={dataKey}
                    stroke={color}
                    fill={`url(#grad-${dataKey})`}
                    strokeWidth={2}
                />
            </AreaChart>
        </ResponsiveContainer>
    );
}

/* ============================
   PIE CHART (Smart grouping)
   ============================ */
const MAX_SLICES = 8;

function CustomPieTooltip({ active, payload }: any) {
    if (!active || !payload?.length) return null;
    const d = payload[0];
    return (
        <div style={{
            background: "rgba(10, 15, 26, 0.95)",
            border: "1px solid rgba(148, 163, 184, 0.15)",
            borderRadius: 10,
            padding: "10px 14px",
            fontSize: 12,
            color: "#f1f5f9",
            boxShadow: "0 8px 24px rgba(0,0,0,0.4)",
        }}>
            <div style={{ fontWeight: 600, marginBottom: 4, color: d.payload?.fill || "#facc15" }}>
                {d.name}
            </div>
            <div style={{ color: "#cbd5e1" }}>
                {typeof d.value === "number" ? d.value.toLocaleString() : d.value}
                {d.payload?.percent != null && (
                    <span style={{ color: "#94a3b8", marginLeft: 6 }}>
                        ({(d.payload.percent * 100).toFixed(1)}%)
                    </span>
                )}
            </div>
            {d.payload?._groupedItems && (
                <div style={{ marginTop: 6, paddingTop: 6, borderTop: "1px solid rgba(255,255,255,0.1)", fontSize: 11, color: "#94a3b8" }}>
                    Includes: {d.payload._groupedItems.join(", ")}
                </div>
            )}
        </div>
    );
}

export function SynPieChart({
    data,
    dataKey,
    nameKey = "name",
    height = 300,
}: {
    data: ChartDatum[];
    dataKey: string;
    nameKey?: string;
    height?: number;
}) {
    const [hovered, setHovered] = useState<number | null>(null);

    // Smart grouping: if more than MAX_SLICES items, group smallest into "Other"
    const { chartData, colorMap } = useMemo(() => {
        if (!data || data.length === 0) return { chartData: [], colorMap: {} as Record<string, string> };

        const sorted = [...data].sort((a, b) => (b[dataKey] || 0) - (a[dataKey] || 0));
        const cMap: Record<string, string> = {};

        if (sorted.length <= MAX_SLICES) {
            sorted.forEach((d, i) => { cMap[d[nameKey]] = COLORS[i % COLORS.length]; });
            return { chartData: sorted, colorMap: cMap };
        }

        // Keep top items, group the rest
        const topItems = sorted.slice(0, MAX_SLICES - 1);
        const remainingItems = sorted.slice(MAX_SLICES - 1);
        const otherValue = remainingItems.reduce((sum, d) => sum + (d[dataKey] || 0), 0);
        const otherNames = remainingItems.map(d => d[nameKey]);

        topItems.forEach((d, i) => { cMap[d[nameKey]] = COLORS[i % COLORS.length]; });
        cMap["Other"] = COLORS[(MAX_SLICES - 1) % COLORS.length];

        const grouped = [
            ...topItems,
            { [nameKey]: "Other", [dataKey]: otherValue, _groupedItems: otherNames },
        ];

        return { chartData: grouped, colorMap: cMap };
    }, [data, dataKey, nameKey]);

    if (chartData.length === 0) {
        return (
            <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height, color: "#94a3b8", fontSize: 13 }}>
                No data available
            </div>
        );
    }

    // Compute total for percentage display in legend
    const total = chartData.reduce((sum, d) => sum + (d[dataKey] || 0), 0);

    return (
        <div style={{ display: "flex", alignItems: "center", gap: 16, height }}>
            {/* Pie */}
            <div style={{ flex: "0 0 55%", height: "100%" }}>
                <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie
                            data={chartData}
                            dataKey={dataKey}
                            nameKey={nameKey}
                            cx="50%"
                            cy="50%"
                            outerRadius={Math.min(height * 0.38, 110)}
                            innerRadius={Math.min(height * 0.2, 55)}
                            paddingAngle={2}
                            label={false}
                            labelLine={false}
                            onMouseEnter={(_, index) => setHovered(index)}
                            onMouseLeave={() => setHovered(null)}
                            stroke="rgba(0,0,0,0.3)"
                            strokeWidth={1}
                        >
                            {chartData.map((entry, i) => (
                                <Cell
                                    key={i}
                                    fill={colorMap[entry[nameKey]] || COLORS[i % COLORS.length]}
                                    opacity={hovered === null || hovered === i ? 1 : 0.4}
                                    style={{ transition: "opacity 0.2s ease", cursor: "pointer" }}
                                />
                            ))}
                        </Pie>
                        <Tooltip content={<CustomPieTooltip />} />
                    </PieChart>
                </ResponsiveContainer>
            </div>

            {/* Legend */}
            <div style={{
                flex: "1 1 45%",
                maxHeight: height - 16,
                overflowY: "auto",
                paddingRight: 4,
                display: "flex",
                flexDirection: "column",
                gap: 4,
            }}
                className="pie-legend-scroll"
            >
                {chartData.map((entry, i) => {
                    const val = entry[dataKey] || 0;
                    const pct = total > 0 ? ((val / total) * 100).toFixed(1) : "0";
                    const name = entry[nameKey];
                    const color = colorMap[name] || COLORS[i % COLORS.length];
                    const isHovered = hovered === i;

                    return (
                        <div
                            key={i}
                            onMouseEnter={() => setHovered(i)}
                            onMouseLeave={() => setHovered(null)}
                            style={{
                                display: "flex",
                                alignItems: "center",
                                gap: 8,
                                padding: "5px 8px",
                                borderRadius: 6,
                                background: isHovered ? "rgba(255,255,255,0.05)" : "transparent",
                                cursor: "pointer",
                                transition: "background 0.15s ease",
                            }}
                        >
                            <span style={{
                                width: 10,
                                height: 10,
                                borderRadius: 3,
                                background: color,
                                flexShrink: 0,
                            }} />
                            <span style={{
                                flex: 1,
                                fontSize: 11,
                                color: isHovered ? "#f1f5f9" : "#cbd5e1",
                                whiteSpace: "nowrap",
                                overflow: "hidden",
                                textOverflow: "ellipsis",
                                fontWeight: isHovered ? 600 : 400,
                                transition: "color 0.15s ease",
                            }}>
                                {name}
                            </span>
                            <span style={{
                                fontSize: 11,
                                color: isHovered ? color : "#64748b",
                                fontWeight: 600,
                                fontFamily: "var(--font-mono, monospace)",
                                flexShrink: 0,
                                transition: "color 0.15s ease",
                            }}>
                                {pct}%
                            </span>
                        </div>
                    );
                })}
            </div>
        </div>
    );
}
