"use client";
import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  LayoutDashboard, Upload, BarChart3, Network, Bot, Download,
  Activity, Brain, Dna, Plug, GitBranch, ChevronLeft,
} from "lucide-react";
import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

const NAV_SECTIONS = [
  {
    label: "Intelligence",
    items: [
      { label: "Command Center", href: "/dashboard", icon: LayoutDashboard },
      { label: "Upload Data", href: "/upload", icon: Upload },
    ],
  },
  {
    label: "Analysis",
    items: [
      { label: "Analytics", href: "/analytics", icon: BarChart3 },
      { label: "Graph Intelligence", href: "/graph", icon: Network },
      { label: "AI Co-Pilot", href: "/copilot", icon: Bot },
      { label: "Causal Genome", href: "/causal", icon: Dna },
      { label: "XAI / Explainability", href: "/xai", icon: Brain },
    ],
  },
  {
    label: "Platform",
    items: [
      { label: "Connectors", href: "/connectors", icon: Plug },
      { label: "Pipeline Monitor", href: "/pipeline", icon: GitBranch },
      { label: "Export Hub", href: "/export", icon: Download },
    ],
  },
];

export default function Sidebar() {
  const pathname = usePathname();
  const [collapsed, setCollapsed] = useState(false);

  return (
    <aside
      className="sidebar"
      style={{ width: collapsed ? "var(--sidebar-collapsed)" : "var(--sidebar-width)" }}
    >
      {/* Logo */}
      <Link href="/" style={{ textDecoration: "none" }}>
        <div className="sidebar-logo">
          <div className="sidebar-logo-icon">N</div>
          {!collapsed && <div className="sidebar-logo-text">NEXUS</div>}
        </div>
      </Link>

      {/* Navigation */}
      <nav className="sidebar-nav" style={{ flex: 1 }}>
        {NAV_SECTIONS.map((section) => (
          <div key={section.label}>
            {!collapsed && <div className="sidebar-section">{section.label}</div>}
            {section.items.map((item) => (
              <Link
                key={item.href}
                href={item.href}
                className={`sidebar-link ${pathname === item.href ? "active" : ""}`}
                title={collapsed ? item.label : undefined}
              >
                <item.icon size={18} />
                {!collapsed && <span>{item.label}</span>}
              </Link>
            ))}
          </div>
        ))}
      </nav>

      {/* Collapse toggle */}
      <div style={{ padding: "8px 12px", borderTop: "1px solid var(--color-border-subtle)" }}>
        <button
          onClick={() => setCollapsed(!collapsed)}
          className="sidebar-link"
          style={{ width: "100%", border: "none", background: "none", cursor: "pointer", fontFamily: "var(--font-sans)" }}
        >
          <motion.div
            animate={{ rotate: collapsed ? 180 : 0 }}
            transition={{ duration: 0.2 }}
            style={{ display: "flex", alignItems: "center" }}
          >
            <ChevronLeft size={18} />
          </motion.div>
          {!collapsed && <span>Collapse</span>}
        </button>

        <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 12px" }}>
          <Activity size={14} color="var(--color-success)" />
          {!collapsed && (
            <span style={{ fontSize: 11, color: "var(--color-text-muted)" }}>
              NEXUS v3.0 · Online
            </span>
          )}
        </div>
      </div>
    </aside>
  );
}
